<?php
/**
 * The filters of a list (the builder's facets, docs/spec/facets.md of Histeon): search, terms, field values, ranges,
 * sorting and pages, read from the query string — doc 25 of Histeon Publish, D6: the theme carries them.
 *
 * The definitions come from the filter `fondamenta_facets` (name → definition): the site theme generated by the
 * conversion adds them from its `facets.json`. A definition is data only — the base query as `WP_Query` arguments,
 * the results per page, the page parameter, the filters with the meta key of each field already resolved. Visitors
 * choose only among what it allows: unknown parameters are ignored and never repeated in links, terms must exist,
 * sort options must be defined, pages are bounded, texts are cleaned and cut. The query keeps every rule of a loop
 * (fondamenta_query()).
 *
 * @package Fondamenta
 */

declare(strict_types=1);

/** Posts scanned to count the options of a filter: counts are exact up to this many results. */
const FONDAMENTA_FILTRI_SCANSIONE = 2000;

/**
 * The definitions of this site, checked.
 *
 * @return array<string, array<string, mixed>>
 */
function fondamenta_filtri_definizioni(): array {
	$stored = apply_filters( 'fondamenta_facets', array() );
	$out    = array();
	foreach ( is_array( $stored ) ? $stored : array() as $name => $facet ) {
		if ( ! is_string( $name ) || 1 !== preg_match( '/^[a-z][a-z0-9_]{0,30}$/', $name ) || ! is_array( $facet ) || ! is_array( $facet['base'] ?? null ) || ! is_array( $facet['filters'] ?? null ) ) {
			continue;
		}
		$filters = array();
		foreach ( array_slice( $facet['filters'], 0, 10 ) as $filter ) {
			if ( is_array( $filter ) && is_string( $filter['key'] ?? null ) && 1 === preg_match( '/^[a-z][a-z0-9_-]{0,30}$/', $filter['key'] ) && in_array( $filter['kind'] ?? null, array( 'search', 'taxonomy', 'field', 'range', 'sort' ), true ) ) {
				$filters[] = $filter;
			}
		}
		$page_key       = is_string( $facet['pageKey'] ?? null ) && 1 === preg_match( '/^[a-z][a-z0-9_-]{0,30}$/', $facet['pageKey'] ) ? $facet['pageKey'] : 'pagina';
		$out[ $name ] = array(
			'base'    => $facet['base'],
			'perPage' => max( 1, min( FONDAMENTA_MASSIMO, (int) ( $facet['perPage'] ?? 10 ) ) ),
			'pageKey' => $page_key,
			'filters' => $filters,
		);
	}
	return $out;
}

/**
 * The state of a filtered list for this request (as the builder's `facets.<name>`); null when it does not exist.
 * Results are post IDs.
 *
 * @return array<string, mixed>|null
 */
function fondamenta_filtro( string $name ): ?array {
	static $memo = array();
	// Once per list and query string (a test, or a proof, may draw the same page with other parameters).
	$key = $name . '?' . md5( (string) wp_json_encode( $_GET ) ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- only a cache key.
	if ( ! array_key_exists( $key, $memo ) ) {
		$facet        = fondamenta_filtri_definizioni()[ $name ] ?? null;
		$memo[ $key ] = null === $facet ? null : fondamenta_filtro_calcola( $name, $facet );
		if ( null !== $memo[ $key ] ) {
			$GLOBALS['fondamenta_filtri'] = true;
		}
	}
	return $memo[ $key ];
}

/**
 * @param array<string, mixed> $facet One of fondamenta_filtri_definizioni().
 * @return array<string, mixed>|null
 */
function fondamenta_filtro_calcola( string $name, array $facet ): ?array {
	/** @var list<array<string, mixed>> $filters */
	$filters = $facet['filters'];
	$values  = array();
	foreach ( $filters as $filter ) {
		$values[ $filter['key'] ] = fondamenta_filtro_scelta( $filter );
	}
	$per_page = (int) $facet['perPage'];
	$page_key = (string) $facet['pageKey'];
	$asked    = fondamenta_filtro_parametro( $page_key );
	$page     = is_string( $asked ) && ctype_digit( $asked ) ? max( 1, min( 1000, (int) $asked ) ) : 1;

	$result = fondamenta_filtro_pagina( fondamenta_filtro_applica( $facet['base'], $filters, $values ), $per_page, $page );
	if ( null === $result ) {
		return null;
	}
	if ( array() === $result['items'] && $page > 1 ) {
		// Past the last page (WordPress then counts nothing): the last page with results.
		$first  = fondamenta_filtro_pagina( fondamenta_filtro_applica( $facet['base'], $filters, $values ), $per_page, 1 ) ?? $result;
		$page   = max( 1, (int) ceil( $first['total'] / $per_page ) );
		$result = fondamenta_filtro_pagina( fondamenta_filtro_applica( $facet['base'], $filters, $values ), $per_page, $page ) ?? $first;
	}
	$total = $result['total'];
	$pages = max( 1, (int) ceil( $total / $per_page ) );
	$link  = static fn ( array $next, int $to = 1 ): string => fondamenta_filtro_indirizzo( $filters, $next, $page_key, $to );
	$state = array(
		'items'      => $result['items'],
		'total'      => $total,
		'page'       => $page,
		'pages'      => $pages,
		'perPage'    => $per_page,
		'pageKey'    => $page_key,
		'action'     => fondamenta_filtro_percorso(),
		'hidden'     => array(),
		'values'     => array(),
		'filters'    => array(),
		'active'     => array(),
		'hasFilters' => false,
		'resetUrl'   => $link( array() ),
		'prevUrl'    => $page > 1 ? $link( $values, $page - 1 ) : null,
		'nextUrl'    => $page < $pages ? $link( $values, $page + 1 ) : null,
		'pageLinks'  => fondamenta_filtro_pagine( $page, $pages, static fn ( int $to ): string => $link( $values, $to ) ),
	);
	foreach ( $filters as $filter ) {
		$key      = (string) $filter['key'];
		$value    = $values[ $key ];
		$multiple = 'taxonomy' === $filter['kind'] && ! empty( $filter['multiple'] );
		$options  = fondamenta_filtro_opzioni( $facet['base'], $filters, $values, $filter, $link );
		$entry    = array(
			'kind'     => $filter['kind'],
			'key'      => $key,
			'label'    => (string) ( $filter['label'] ?? $key ),
			'name'     => $multiple ? $key . '[]' : $key,
			'multiple' => $multiple,
			'value'    => $value,
			'options'  => $options,
		);
		if ( 'range' === $filter['kind'] ) {
			[ $entry['min'], $entry['max'] ] = is_string( $value ) ? array_pad( explode( '..', $value, 2 ), 2, '' ) : array( '', '' );
		}
		$state['values'][ $key ]  = $value;
		$state['filters'][ $key ] = $entry;
		foreach ( $options as $option ) {
			if ( $option['selected'] && 'sort' !== $filter['kind'] ) {
				$state['active'][] = array(
					'key'   => $key,
					'label' => $entry['label'],
					'value' => $option['value'],
					'text'  => $option['label'],
					'url'   => $option['url'],
				);
			}
		}
		if ( ( 'search' === $filter['kind'] || 'range' === $filter['kind'] ) && null !== $value ) {
			$state['active'][] = array(
				'key'   => $key,
				'label' => $entry['label'],
				'value' => $value,
				'text'  => $value,
				'url'   => $link( array( $key => null ) + $values ),
			);
		}
	}
	$state['hasFilters'] = array() !== $state['active'];
	return $state;
}

/**
 * One page of results with the total; null when the base query lists nothing a visitor may see.
 *
 * @param array<string, mixed> $query
 * @return array{items: list<int>, total: int}|null
 */
function fondamenta_filtro_pagina( array $query, int $per_page, int $page ): ?array {
	$args = fondamenta_query( $query );
	if ( null === $args ) {
		return null;
	}
	$args['posts_per_page'] = $per_page;
	$args['paged']          = $page;
	$args['no_found_rows']  = false;
	$args['fields']         = 'ids';
	unset( $args['offset'] );
	$wp_query = new WP_Query( fondamenta_ordine_stabile( $args ) );
	return array(
		'items' => array_map( 'intval', $wp_query->posts ),
		'total' => (int) $wp_query->found_posts,
	);
}

/**
 * The value a visitor chose for a filter, checked: null when absent or not allowed.
 *
 * @param array<string, mixed> $filter
 * @return string|list<string>|null
 */
function fondamenta_filtro_scelta( array $filter ): string|array|null {
	$raw  = fondamenta_filtro_parametro( (string) $filter['key'] );
	$meta = is_string( $filter['meta'] ?? null ) ? $filter['meta'] : '';
	switch ( $filter['kind'] ) {
		case 'search':
		case 'field':
			$text = is_string( $raw ) ? trim( mb_substr( $raw, 0, 100 ) ) : '';
			if ( 'field' === $filter['kind'] && '' === $meta ) {
				return null;
			}
			return '' === $text ? null : $text;
		case 'range':
			if ( '' === $meta ) {
				return null;
			}
			$side  = static fn ( string|array|null $v ): string => is_string( $v ) ? trim( mb_substr( $v, 0, 30 ) ) : '';
			$text  = is_string( $raw ) && str_contains( $raw, '..' ) ? $raw : $side( fondamenta_filtro_parametro( $filter['key'] . '_min' ) ) . '..' . $side( fondamenta_filtro_parametro( $filter['key'] . '_max' ) );
			$sides = array_map( 'trim', explode( '..', $text, 2 ) );
			$valid = static fn ( string $v ): bool => '' === $v || ( 'date' === ( $filter['type'] ?? 'number' ) ? 1 === preg_match( '/^\d{4}-\d{2}-\d{2}$/', $v ) : is_numeric( $v ) && strlen( $v ) <= 20 );
			if ( 2 !== count( $sides ) || ! $valid( $sides[0] ) || ! $valid( $sides[1] ) || ( '' === $sides[0] && '' === $sides[1] ) ) {
				return null;
			}
			return $sides[0] . '..' . $sides[1];
		case 'sort':
			foreach ( is_array( $filter['options'] ?? null ) ? $filter['options'] : array() as $option ) {
				if ( is_array( $option ) && $raw === ( $option['value'] ?? null ) ) {
					return $raw;
				}
			}
			return null;
		case 'taxonomy':
			$slugs = is_array( $raw ) ? $raw : ( is_string( $raw ) ? explode( ',', $raw ) : array() );
			$out   = array();
			foreach ( array_slice( $slugs, 0, 20 ) as $slug ) {
				$slug = sanitize_title( $slug );
				if ( '' !== $slug && ! in_array( $slug, $out, true ) && get_term_by( 'slug', $slug, (string) ( $filter['taxonomy'] ?? '' ) ) instanceof WP_Term ) {
					$out[] = $slug;
				}
			}
			if ( empty( $filter['multiple'] ) ) {
				$out = array_slice( $out, 0, 1 );
			}
			return array() === $out ? null : $out;
	}
	return null;
}

/**
 * A query string parameter, sanitized text (or a list of texts); null when absent.
 *
 * @return string|list<string>|null
 */
function fondamenta_filtro_parametro( string $key ): string|array|null {
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only filtering of public content.
	$raw = isset( $_GET[ $key ] ) ? wp_unslash( $_GET[ $key ] ) : null;
	if ( is_string( $raw ) ) {
		return sanitize_text_field( $raw );
	}
	if ( is_array( $raw ) ) {
		return array_values( array_map( 'sanitize_text_field', array_filter( array_slice( $raw, 0, 20 ), 'is_string' ) ) );
	}
	return null;
}

/**
 * The base query with the chosen values (all of them, or all but one filter's to count its options).
 *
 * @param array<string, mixed>                    $base
 * @param list<array<string, mixed>>              $filters
 * @param array<string, string|list<string>|null> $values
 * @return array<string, mixed>
 */
function fondamenta_filtro_applica( array $base, array $filters, array $values, ?string $except = null ): array {
	$query = $base;
	$tax   = array();
	$meta  = array();
	foreach ( $filters as $filter ) {
		$value = $values[ $filter['key'] ] ?? null;
		$key   = is_string( $filter['meta'] ?? null ) ? $filter['meta'] : '';
		if ( null === $value || $filter['key'] === $except ) {
			continue;
		}
		switch ( $filter['kind'] ) {
			case 'search':
				$query['s'] = $value;
				break;
			case 'taxonomy':
				$tax[] = array(
					'taxonomy' => (string) ( $filter['taxonomy'] ?? '' ),
					'field'    => 'slug',
					'terms'    => (array) $value,
					'operator' => 'all' === ( $filter['match'] ?? 'any' ) ? 'AND' : 'IN',
				);
				break;
			case 'field':
				if ( '' !== $key ) {
					$meta[] = array(
						'key'     => $key,
						'value'   => $value,
						'compare' => '=',
					);
				}
				break;
			case 'range':
				if ( '' !== $key && is_string( $value ) ) {
					[ $min, $max ] = array_pad( explode( '..', $value, 2 ), 2, '' );
					$cast          = 'date' === ( $filter['type'] ?? 'number' ) ? 'DATE' : 'NUMERIC';
					$meta[]        = '' !== $min && '' !== $max
						? array( 'key' => $key, 'value' => array( $min, $max ), 'compare' => 'BETWEEN', 'type' => $cast )
						: array( 'key' => $key, 'value' => '' !== $min ? $min : $max, 'compare' => '' !== $min ? '>=' : '<=', 'type' => $cast );
				}
				break;
			case 'sort':
				foreach ( is_array( $filter['options'] ?? null ) ? $filter['options'] : array() as $option ) {
					if ( ! is_array( $option ) || ( $option['value'] ?? null ) !== $value ) {
						continue;
					}
					$query['order'] = 'asc' === strtolower( (string) ( $option['order'] ?? 'desc' ) ) ? 'ASC' : 'DESC';
					$orderby        = (string) ( $option['orderby'] ?? 'date' );
					if ( 'field' !== $orderby ) {
						$query['orderby'] = in_array( $orderby, array( 'date', 'title', 'modified', 'menu_order', 'comment_count', 'rand' ), true ) ? $orderby : 'date';
						continue;
					}
					// By a public field: contents without it are left out, as WordPress does with meta_key.
					if ( is_string( $option['meta'] ?? null ) && '' !== $option['meta'] ) {
						$query['meta_key'] = $option['meta']; // phpcs:ignore WordPress.DB.SlowDBQuery
						$query['orderby']  = ! empty( $option['numeric'] ) ? 'meta_value_num' : 'meta_value';
					}
				}
				break;
		}
	}
	if ( array() !== $tax ) {
		$own                = is_array( $base['tax_query'] ?? null ) && array() !== $base['tax_query'] ? array( $base['tax_query'] ) : array();
		$query['tax_query'] = array_merge( array( 'relation' => 'AND' ), $own, $tax ); // phpcs:ignore WordPress.DB.SlowDBQuery
	}
	if ( array() !== $meta ) {
		$own                 = is_array( $base['meta_query'] ?? null ) && array() !== $base['meta_query'] ? array( $base['meta_query'] ) : array();
		$query['meta_query'] = array_merge( array( 'relation' => 'AND' ), $own, $meta ); // phpcs:ignore WordPress.DB.SlowDBQuery
	}
	return $query;
}

/**
 * The options of a filter, each with how many results it would give (the other filters applied), whether it is
 * chosen and the link that chooses or removes it.
 *
 * @param array<string, mixed>                    $base
 * @param list<array<string, mixed>>              $filters
 * @param array<string, string|list<string>|null> $values
 * @param array<string, mixed>                    $filter
 * @param callable(array<string, mixed>): string  $link
 * @return list<array{value: string, label: string, count: int|null, selected: bool, url: string}>
 */
function fondamenta_filtro_opzioni( array $base, array $filters, array $values, array $filter, callable $link ): array {
	$key   = (string) $filter['key'];
	$value = $values[ $key ];
	$out   = array();
	if ( 'sort' === $filter['kind'] ) {
		foreach ( is_array( $filter['options'] ?? null ) ? $filter['options'] : array() as $option ) {
			if ( ! is_array( $option ) || ! is_string( $option['value'] ?? null ) ) {
				continue;
			}
			$out[] = array(
				'value'    => $option['value'],
				'label'    => (string) ( $option['label'] ?? $option['value'] ),
				'count'    => null,
				'selected' => $option['value'] === $value,
				'url'      => $link( array( $key => $option['value'] ) + $values ),
			);
		}
		return $out;
	}
	if ( 'search' === $filter['kind'] || 'range' === $filter['kind'] ) {
		return array();
	}
	$ids  = array();
	$args = fondamenta_query( fondamenta_filtro_applica( $base, $filters, $values, $key ) );
	if ( null !== $args ) {
		unset( $args['paged'], $args['offset'], $args['orderby'], $args['order'] );
		$args['posts_per_page'] = FONDAMENTA_FILTRI_SCANSIONE;
		$args['fields']         = 'ids';
		$ids                    = array_map( 'intval', ( new WP_Query( $args ) )->posts );
	}
	$counts = array();
	$labels = array();
	if ( 'taxonomy' === $filter['kind'] ) {
		$taxonomy = (string) ( $filter['taxonomy'] ?? '' );
		$terms    = array() === $ids ? array() : wp_get_object_terms( $ids, $taxonomy, array( 'fields' => 'all_with_object_id' ) );
		foreach ( is_array( $terms ) ? $terms : array() as $term ) {
			$counts[ $term->slug ] = ( $counts[ $term->slug ] ?? 0 ) + 1;
			$labels[ $term->slug ] = $term->name;
		}
		foreach ( (array) $value as $slug ) {
			$term = get_term_by( 'slug', (string) $slug, $taxonomy );
			if ( $term instanceof WP_Term ) {
				$counts[ $term->slug ] = $counts[ $term->slug ] ?? 0;
				$labels[ $term->slug ] = $term->name;
			}
		}
	} else {
		$meta = is_string( $filter['meta'] ?? null ) ? $filter['meta'] : '';
		if ( '' !== $meta && array() !== $ids ) {
			update_meta_cache( 'post', $ids );
			foreach ( $ids as $id ) {
				$v = get_post_meta( $id, $meta, true );
				if ( is_scalar( $v ) && '' !== (string) $v && mb_strlen( (string) $v ) <= 100 ) {
					$counts[ (string) $v ] = ( $counts[ (string) $v ] ?? 0 ) + 1;
					$labels[ (string) $v ] = (string) $v;
				}
			}
		}
		if ( is_string( $value ) ) {
			$counts[ $value ] = $counts[ $value ] ?? 0;
			$labels[ $value ] = $value;
		}
	}
	uksort( $counts, static fn ( int|string $a, int|string $b ): int => strnatcasecmp( $labels[ (string) $a ], $labels[ (string) $b ] ) );
	foreach ( array_slice( $counts, 0, 50, true ) as $option => $count ) {
		$option   = (string) $option;
		$chosen   = (array) $value;
		$selected = in_array( $option, $chosen, true );
		if ( ! empty( $filter['multiple'] ) ) {
			$next = $selected ? array_values( array_diff( $chosen, array( $option ) ) ) : array_merge( $chosen, array( $option ) );
		} else {
			$next = $selected ? null : ( 'taxonomy' === $filter['kind'] ? array( $option ) : $option );
		}
		$out[] = array(
			'value'    => $option,
			'label'    => $labels[ $option ],
			'count'    => $count,
			'selected' => $selected,
			'url'      => $link( array( $key => array() === $next ? null : $next ) + $values ),
		);
	}
	return $out;
}

/**
 * A link to this page with these values (only the filters' own parameters; lists as a, b, c) and page.
 *
 * @param list<array<string, mixed>>              $filters
 * @param array<string, string|list<string>|null> $values
 */
function fondamenta_filtro_indirizzo( array $filters, array $values, string $page_key, int $page ): string {
	$parts = array();
	foreach ( $filters as $filter ) {
		$value = $values[ $filter['key'] ] ?? null;
		if ( null === $value || array() === $value ) {
			continue;
		}
		$parts[] = rawurlencode( (string) $filter['key'] ) . '=' . implode( ',', array_map( 'rawurlencode', array_map( 'strval', (array) $value ) ) );
	}
	if ( $page > 1 ) {
		$parts[] = rawurlencode( $page_key ) . '=' . $page;
	}
	return fondamenta_filtro_percorso() . ( array() === $parts ? '' : '?' . implode( '&', $parts ) );
}

/** The path of the current page, without its query string. */
function fondamenta_filtro_percorso(): string {
	$uri  = isset( $_SERVER['REQUEST_URI'] ) ? sanitize_text_field( wp_unslash( (string) $_SERVER['REQUEST_URI'] ) ) : '/';
	$path = wp_parse_url( $uri, PHP_URL_PATH );
	return is_string( $path ) && str_starts_with( $path, '/' ) && ! str_starts_with( $path, '//' ) ? $path : '/';
}

/**
 * Links to the pages around the current one, the first and the last; a gap is an entry without number.
 *
 * @param callable(int): string $link
 * @return list<array{number: int|null, url: string|null, current: bool}>
 */
function fondamenta_filtro_pagine( int $page, int $pages, callable $link ): array {
	if ( $pages <= 1 ) {
		return array();
	}
	$out  = array();
	$last = 0;
	for ( $n = 1; $n <= $pages; $n++ ) {
		if ( 1 !== $n && $pages !== $n && abs( $n - $page ) > 2 ) {
			continue;
		}
		if ( $n - $last > 1 ) {
			$out[] = array(
				'number'  => null,
				'url'     => null,
				'current' => false,
			);
		}
		$out[] = array(
			'number'  => $n,
			'url'     => $link( $n ),
			'current' => $n === $page,
		);
		$last  = $n;
	}
	return $out;
}

/**
 * A value of a filtered list by the builder's path (`total`, `values.q`, `filters.tema.label`…).
 *
 * @param list<string> $path
 */
function fondamenta_filtro_valore( string $name, array $path ): mixed {
	$state = fondamenta_filtro( $name );
	if ( null === $state || array() === $path || in_array( $path[0], array( 'items', 'pageLinks', 'active', 'hidden' ), true ) ) {
		return null;
	}
	$value = $state;
	foreach ( $path as $step ) {
		if ( ! is_array( $value ) || ! array_key_exists( $step, $value ) || 'options' === $step ) {
			return null;
		}
		$value = $value[ $step ];
	}
	return $value;
}

/**
 * The items of a loop over a filtered list, as block context: the results (posts), or the options of a filter, the
 * active filters, the page links, the hidden fields (values).
 *
 * @param array<string, mixed> $attributes
 * @return list<array<string, mixed>>
 */
function fondamenta_filtro_voci( array $attributes ): array {
	$state = fondamenta_filtro( (string) ( $attributes['facet'] ?? '' ) );
	if ( null === $state ) {
		return array();
	}
	$list = match ( (string) ( $attributes['elenco'] ?? 'risultati' ) ) {
		'opzioni' => $state['filters'][ (string) ( $attributes['filtro'] ?? '' ) ]['options'] ?? array(),
		'attivi' => $state['active'],
		'pagine' => $state['pageLinks'],
		'nascosti' => $state['hidden'],
		default => null,
	};
	if ( null === $list ) {
		$out = array();
		foreach ( $state['items'] as $id ) {
			$post = get_post( $id );
			if ( $post instanceof WP_Post ) {
				$out[] = array(
					'postId'          => $post->ID,
					'postType'        => $post->post_type,
					'fondamenta/voce' => array( 'post' => $post->ID ),
				);
			}
		}
		return $out;
	}
	return array_map( static fn ( array $entry ): array => array( 'fondamenta/voce' => array( 'dato' => $entry ) ), array_values( $list ) );
}

// The builder's script that refreshes the results without reloading (the forms and links work without it): the
// same file, copied by theme/build.sh, on pages that show a filtered list.
add_action(
	'wp_footer',
	static function (): void {
		if ( empty( $GLOBALS['fondamenta_filtri'] ) || defined( 'XB_VERSION' ) ) {
			return;
		}
		wp_enqueue_script( 'fondamenta-filtri', get_template_directory_uri() . '/assets/facets.js', array(), (string) wp_get_theme( 'fondamenta' )->get( 'Version' ), array( 'in_footer' => true ) );
	},
	1
);
